/**
* Extracts slide text and speaker notes from a PPTX file using JSZip
*/
async function extractTextFromPPTX(file) {
	const fileNameLower = file.name.toLowerCase();
	if (fileNameLower.endsWith(".ppt") && !fileNameLower.endsWith(".pptx")) throw new Error("Legacy PowerPoint .ppt files cannot be parsed directly in the browser. Please open the file in PowerPoint or Google Slides and Save As/Download as .pptx or .pdf, or copy-paste the slide text directly.");
	try {
		const zip = new import_jszip_min.default();
		const arrayBuffer = await file.arrayBuffer();
		const loadedZip = await zip.loadAsync(arrayBuffer);
		const slideFileNames = Object.keys(loadedZip.files).filter((name) => name.match(/^ppt\/slides\/slide\d+\.xml$/i));
		if (slideFileNames.length === 0) throw new Error("No slide XML files found inside PPTX presentation. The presentation archive might be corrupted or password-protected.");
		slideFileNames.sort((a, b) => {
			const matchA = a.match(/\d+/);
			const matchB = b.match(/\d+/);
			return (matchA ? parseInt(matchA[0], 10) : 0) - (matchB ? parseInt(matchB[0], 10) : 0);
		});
		const slides = [];
		let hasSpeakerNotes = false;
		for (let i = 0; i < slideFileNames.length; i++) {
			const slidePath = slideFileNames[i];
			const slideText = ((await loadedZip.files[slidePath].async("string")).match(/<a:t[^>]*>([^<]*)<\/a:t>/gi) || []).map((tag) => tag.replace(/<[^>]+>/g, "").trim()).filter((text) => text.length > 0).join(" ");
			let notesText = "";
			const notesFile = loadedZip.files[`ppt/notesSlides/notesSlide${i + 1}.xml`];
			if (notesFile) try {
				const noteContent = ((await notesFile.async("string")).match(/<a:t[^>]*>([^<]*)<\/a:t>/gi) || []).map((t) => t.replace(/<[^>]+>/g, "").trim()).filter((t) => t.length > 0 && !t.match(/^\d+$/)).join(" ");
				if (noteContent.length > 0) {
					notesText = `\n[Speaker Notes: ${noteContent}]`;
					hasSpeakerNotes = true;
				}
			} catch {}
			if (slideText.trim().length > 0 || notesText.length > 0) slides.push(`[SLIDE ${i + 1}]\n${slideText}${notesText}`);
		}
		if (slides.length === 0) throw new Error("Could not extract text from PPTX. The slides appear to consist entirely of scanned images or screenshots without embedded text. Try uploading as a PDF or pasting the slide notes.");
		const fullText = slides.join("\n\n");
		const wordCount = fullText.split(/\s+/).filter(Boolean).length;
		return {
			text: fullText,
			slideCount: slides.length,
			wordCount,
			hasNotes: hasSpeakerNotes
		};
	} catch (err) {
		console.warn("PPTX parsing error:", err);
		throw new Error(err.message || "Failed to extract text from PowerPoint presentation. Please convert to PDF or paste slide text.");
	}
}
/**
* Extracts text from a Word document (.docx) using JSZip
*/
async function extractTextFromDOCX(file) {
	try {
		const zip = new import_jszip_min.default();
		const arrayBuffer = await file.arrayBuffer();
		const docXml = (await zip.loadAsync(arrayBuffer)).files["word/document.xml"];
		if (!docXml) throw new Error("Not a valid DOCX document.");
		const paragraphs = (await docXml.async("string")).split(/<\/w:p>/);
		const textLines = [];
		for (const p of paragraphs) {
			const line = (p.match(/<w:t[^>]*>([^<]*)<\/w:t>/gi) || []).map((t) => t.replace(/<[^>]+>/g, "").trim()).filter(Boolean).join(" ");
			if (line) textLines.push(line);
		}
		return textLines.join("\n\n");
	} catch (err) {
		throw new Error(err.message || "Failed to extract text from Word document. Please copy and paste the text directly.");
	}
}
